import React from "react";

import { EventPerformance, timeData } from '../../models/models';

import ValidationService, { Schema, COMMON_REGEXES } from "../../services/validation.service";
import EventService from "../../services/event.service";
import config from "../../config/config";

import QuickForm, { QuickFormSchemaMetaType } from "../quick-form/quick-form";
import FileBrowser from "../file-browser/file-browser";
import { ModalContext } from "../modal/modal";
import { SCRUDFormComponent } from "../utilities/SCRUD/SCRUD";

import TwoColumns from "../utilities/two-columns/two-columns";
import ColumnSnapper from "../utilities/column-snapper/column-snapper";

const { periods, weekdays, months, daysPerMonth, years, dates, times } = timeData;

const acceptedMedia = [
  'gif', 'jpg', 'jpeg', 'png',
  'mov', 'mp4', 'mpeg', 'webm', 'ogg'
];

const periodPrases = (e: EventPerformance | FormEvent): string => {
  if (
    ([...dates] as any[]).includes(e.day) &&
    ([...months] as any[]).includes(e.month) &&
    ([...years] as any[]).includes(e.year) &&
    ([...periods] as any[]).includes(e.period)
  ) {
    let { year, month, day, period } = (e as EventPerformance);
    const dayNum = (new Date(year, months.indexOf(month), day)).getDay();
    const weekday: typeof weekdays[number] = weekdays[dayNum];
    const dayCount = Math.floor((day-1) / 7) + 1;
    const dayCountSuffix = [ 'st', 'nd', 'rd', 'th', 'th' ];
    return ({
      Once: ``,
      Daily: `Every day`,
      Weekly: `Every ${weekday}`,
      BiWeekly: `Every other ${weekday}`,
      Monthly: `The ${dayCount}${dayCountSuffix[dayCount-1]} ${weekday} of every month`
    })[period];
  }
  return '';
};

type Props = {
  mediaList: string[],
  resolve: (eventPerformance: EventPerformance | null) => any
  initModel?: EventPerformance,
};

type FormEvent = Omit<EventPerformance, "month" | "day" | "year" | "time" | "period"> & { 
  month: "Month" | EventPerformance["month"],
  day: "Day" | EventPerformance["day"],
  year: "Year" | EventPerformance["year"],
  time: "Time" | EventPerformance["time"],
  period: "Period" | EventPerformance["period"]
}

const FileBrowserModal: React.FC<{ resolve: (value: { filename: string } | null) => any }> = ({ resolve }) => {

  return (
    <FileBrowser
      acceptedMediaExtensions={{
        image: ['gif', 'jpg', 'jpeg', 'png']
      }}
      onPick={(file) => {
        if (file) {
          resolve({ filename: file });
        } else {
          // resolve(null);
        }
      }}
    />
  );

}

const MediaBrowserModal: React.FC<{ resolve: (value: { filenames: string[] } | null) => any, initMedia: string[] }> = ({ resolve, initMedia }) => {

  const [mediaList, setMediaList] = React.useState<string[]>(initMedia);
  
  return (
    <div>
      <FileBrowser
        acceptedMediaExtensions={{
          image: ['gif', 'jpg', 'jpeg', 'png'],
          video: ['mov', 'mp4', 'mpeg', 'webm', 'ogg'],
          audio: ['mp3', 'wav', 'ogg']
        }}
        onPick={(file) => {
          if (file) {
            // if medialist already contains file, remove it, otherwise add it
            setMediaList(prev => {
              if (prev.includes(file)) {
                return prev.filter(f => f !== file);
              } else {
                return [...prev, file];
              }
            });
          }
        }}
      />
      <div className="flex justify-end mt-4 mx-8 mb-2">
        <select 
          className="select inline-block border border-gray-300 rounded-lg mx-1 w-2/4 flex-1"
          value={mediaList.length ? mediaList.join(', ') : 'No Media Selected'}
        >
          {
            mediaList.length ? 
              mediaList.map((m, i) => <option key={i+m}>{m}</option>) :
              <option>No Media Selected</option>
          }
        </select>
        <button 
          className="btn btn-primary mr-2"
          onClick={() => resolve({ filenames: mediaList })}
        >
          Submit
        </button>
        <button 
          className="btn btn-warning"
          onClick={() => resolve(null)}
        >
          Cancel
        </button>
      </div>
    </div>
  );

}

const EventSCRUDForm: React.FC<SCRUDFormComponent<EventPerformance>> = ({ initModel, onSubmit, onCancel }) => {

  const eventSchema: Schema = {
    day: { type: 'number', attributes: { required: true, range: { min: 1, max: 31 } } },
    month: { type: [...months], attributes: { required: true } },
    year: { type: 'number', attributes: { required: true, range: { min: 2020, max: 2120 } } },
    time: { type: [...times], attributes: { required: true }},
    location: { type: 'string', attributes: { required: true } },
    addressa: { type: 'string', attributes: { required: false }},
    addressb: { type: 'string', attributes: { required: false }},
    thumbnail: { type: 'string', attributes: { required: false } },
    description: { type: 'string', attributes: { required: true, strLength: { minLength: 5 } }},
    website: { type: 'string', attributes: { required: false }},
    media: { type: 'string', attributes: { required: false, array: { minLength: 0 }}},
    period: { type: [...periods], attributes: { required: true } }
  };

  const modalContext = React.useContext(ModalContext);
  const [touched, setTouched] = React.useState<boolean>(false);
  const [event, setEvent] = React.useState<FormEvent>({
    id: initModel?.id || -1, timestamp: initModel?.timestamp || -1,
    day: initModel?.day || "Day", month: initModel?.month ||'Month', year: initModel?.year || "Year", 
    time: initModel?.time ||"Time", website: initModel?.website || '', location: initModel?.location ||'', 
    addressa: initModel?.addressa || "", addressb: initModel?.addressb || "",
    thumbnail: initModel?.thumbnail || '', description: initModel?.description || '', period: initModel?.period || 'Period', media: initModel?.media || []
  });
  const [formErrors, setFormErrors] = React.useState<{ [key: string]: string[] }>({});
  const firstRender = React.useRef<number>(2);

  React.useEffect(() => {
    (async () => {
      let vErrors = (await ValidationService.validate(event, eventSchema)).body;
      let errorKeys: string[] = [];
      vErrors?.forEach(err => {
        if (!errorKeys.includes(err.split(" ")[0])) {
          errorKeys.push(err.split(" ")[0])
        }
      });
      let errorObj: { [key: string]: string[] } = {};
      errorKeys.forEach(key => {
        errorObj[key] = (vErrors?.filter(err => err.split(' ')[0] === key)!).map(err => err.split(' ').slice(1).join(' '))
      });
      setFormErrors(errorObj);
      (!touched && !firstRender.current) && setTouched(true);
      firstRender.current  && (firstRender.current -= 1);

      // (typeof schema[key].type === 'string' && !((<string>schema[key].type).includes(typeof input)))
      // console.log(event);
    })();
  }, [event]);

  return (
    <div className="inline-block w-full mx-auto">

      <div className="border border-gray-300 rounded shadow-md p-6">
        <TwoColumns>

          <div className="p-4 flex flex-col items-center ">
            <div 
              className='w-full max-w-xs aspect-1 border border-gray-300 rounded shadow-md p-0 relative cursor-pointer'
              onClick={async () => {
                const modalRes = await (new Promise<{ filename: string} | null>((res, rej) => modalContext.modal!({
                  node: <FileBrowserModal resolve={res} />,
                  resolve: res , reject: rej
                })));
                modalContext.modal!();
                console.log(modalRes);
                if (modalRes && modalRes.filename) {
                  setEvent(prev => ({ ...prev, thumbnail: modalRes.filename }));                
                }
              }}
            >
              <span
                className="pointer-events-none absolute -top-9 left-10 opacity-0 p-2 transition-opacity group-hover:opacity-100 bg-slate-200 border-gray-300 rounded shadow-md"
              >
                Change Image
              </span>
              <img 
                src={
                  (
                    event.thumbnail.toUpperCase().startsWith('HTTP://') ||
                    event.thumbnail.toUpperCase().startsWith('HTTPS://') ||
                    event.thumbnail.toUpperCase().startsWith('www.')
                  ) ?
                    event.thumbnail
                  :
                    config.ASSETS[config.ENVIRONMENT]+"media/"+event.thumbnail
                } alt="Event Pic" className="object-cover w-full h-full rounded cursor-pointer" 
              />
            </div>

            <button 
              className="btn btn-sm btn-secondary mt-4 !h-9 w-full max-w-xs"
              onClick={async () => {
                const modalRes = await (new Promise<{ filenames: string[] } | null>((res, rej) => modalContext.modal!({
                  node: <MediaBrowserModal resolve={res} initMedia={event.media} />,
                  resolve: res , reject: rej
                })));
                modalContext.modal!();
                if (modalRes && modalRes.filenames) {
                  setEvent(prev => ({ ...prev, media: [ ...modalRes.filenames ] }));
                }
              }}
            >
              Additional Media
            </button>


          </div>
          <div className="p-2">
            <div className="text-lg font-semibold flex flex-wrap justify-between items-center w-[calc(100%-16px)] m-2 pb-1">
              <div className="grow shrink-0 min-w-[120px]">
                <select 
                  className={`select select-sm block border border-gray-300 rounded-lg w-full ${touched && (Object.keys(formErrors).includes('month') ? 'border-red-500' : 'border-green-500')}`}
                  value={event.month}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setEvent(prev => ({ ...prev, month: (e.target.value as typeof months[number]) }))}
                >
                  {
                    ['Month', ...months].map((m, i) => <option key={i+m}>{m}</option>)
                  }
                </select>
              </div>
              <div className="grow shrink-0 min-w-[96px]">
                <select 
                  className={`select select-sm block border border-gray-300 rounded-lg w-full ${touched && (Object.keys(formErrors).includes('day') ? 'border-red-500' : 'border-green-500')}`}
                  value={event.day}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setEvent(prev => ({ ...prev, day: e.target.value === 'Day' ? 'Day' : (parseInt(e.target.value) as typeof dates[number]) }))}
                >
                  {
                    ['Day', ...Array(daysPerMonth[[...months, 'Month'].indexOf(event.month)]).keys()].map((d, i) => <option key={i+d.toString()}>{d === 'Day' ? d : (d as number)+1}</option>)
                  }
                </select>
              </div>
              <div className="hidden md:block">
                &nbsp;,&nbsp;
              </div>
              <div className="grow shrink-0 min-w-[96px]">
                <select 
                  className={`select select-sm block border border-gray-300 rounded-lg w-full  ${touched && (Object.keys(formErrors).includes('year') ? 'border-red-500' : 'border-green-500')}`}
                  value={event.year}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setEvent(prev => ({ ...prev, year: e.target.value === 'Year' ? 'Year' : (parseInt(e.target.value) as typeof years[number]) }))}
                >
                  {
                    ['Year', ...years].map((y, i) => (<option key={i+y.toString()}>{y}</option>))
                  }
                </select>
              </div>
              <div className="grow shrink-0 min-w-[120px]">
                <select 
                  className={`select select-sm block border border-gray-300 rounded-lg w-full ${touched && (Object.keys(formErrors).includes('time') ? 'border-red-500' : 'border-green-500')}`}
                  value={event.time}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setEvent(prev => ({ ...prev, time: (e.target.value as typeof times[number]) }))}
                >
                  {
                    ['Time', ...times].map((t, i) => <option key={i+t}>{t}</option>)
                  }
                </select>
              </div>
              <div className="grow shrink-0 min-w-[120px]">
                <select
                  className={`select select-sm block border border-gray-300 rounded-lg w-full ${touched && (Object.keys(formErrors).includes('period') ? 'border-red-500' : 'border-green-500')}`}
                  value={event.period}
                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setEvent(prev => ({ ...prev, period: (e.target.value as typeof periods[number])}))}
                >
                  { ['Period', ...periods].map((p, i) => (<option key={i+p}>{p}</option>))}
                </select>
              </div>

            </div>
            
            <TwoColumns leftMinPx={256} rightMinPx={1028} >
              <input 
                className={`min-w-[128px] w-[calc(100%-16px)] block border border-gray-300 rounded-lg p-1 px-3 m-2 h-10 ${touched && (Object.keys(formErrors).includes('location') ? 'border-red-500' : 'border-green-500')}`}
                type="text" 
                placeholder={'Location'} 
                value={event.location} 
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEvent(prev => ({ ...prev, location: e.target.value }))}
              ></input>
              <div className='w-[calc(100%-16px)] flex items-center justify-center pt-1 bg-slate-200 rounded-lg h-10 m-2'> { periodPrases(event) } </div>
            </TwoColumns>

            

            <div className={`w-[calc(100%-16px)] text-lg font-medium m-2`}>
              <input 
                className={`w-full border border-gray-300 rounded-lg p-1 px-3  ${touched && (Object.keys(formErrors).includes('website') ? 'border-red-500' : 'border-green-500')}`} 
                type="text" 
                placeholder={'Address line 1'} 
                value={event.addressa} 
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEvent(prev => ({ ...prev, addressa: e.target.value }))}
              ></input>
            </div>
            <div className={`w-[calc(100%-16px)] text-lg font-medium m-2`}>
              <input 
                className={`w-full block border border-gray-300 rounded-lg p-1 px-3 ${touched && (Object.keys(formErrors).includes('website') ? 'border-red-500' : 'border-green-500')}`} 
                type="text" 
                placeholder={'Address line 2'} 
                value={event.addressb} 
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEvent(prev => ({ ...prev, addressb: e.target.value }))}
              ></input>
            </div>

            <div className={`text-gray-700 mb-4 w-[calc(100%-16px)] m-2`}>
              <textarea 
                rows={4}
                cols={64} //max-w-xs lg:max-w-lg xl:max-w-2xl
                className={`resize-none w-full block p-2.5 bg-gray-50 rounded-lg border border-gray-300 px-3 ${touched && (Object.keys(formErrors).includes('description') ? 'border-red-500' : 'border-green-500')}`} 
                placeholder="Write your event description here..."
                value={event.description}
                onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setEvent(prev => ({ ...prev, description: e.target.value }))}
              ></textarea>
            </div>
            <div className={`w-[calc(100%-16px)] text-lg font-medium m-2`}>
              <input 
                className={`w-full inline-block border border-gray-300 rounded-lg p-1 text-blue-500 hover:underline px-3 ${touched && (Object.keys(formErrors).includes('website') ? 'border-red-500' : 'border-green-500')}`} 
                type="text" 
                placeholder={'Venue Website'} 
                value={event.website} 
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEvent(prev => ({ ...prev, website: e.target.value }))}
              ></input>
            </div>
          </div>


        </TwoColumns>

      </div>
      <div className="flex mt-3">
        {
          (touched && !!Object.keys(formErrors).length) &&
            // <div className="inline-block alert alert-error mr-2 h-12 pl-10 pt-3">{Object.keys(formErrors)[0] + ": " + formErrors[Object.keys(formErrors)[0]][0]}</div>
            <select 
              className="inline-block alert alert-error mr-2 h-12 pt-4 text-sm">
              { // todo: focus input element corresponding to selected error
                Object.keys(formErrors).reduce((opts, key) => [...formErrors[key].map(err => (<option key={key + " " + err} className="text-xs">{key + " " + err}</option>)), ...opts],([] as React.ReactNode[]))
              }
            </select>
        }
        <button className={`btn btn-primary mr-2 ml-auto`} disabled={!touched || !!Object.keys(formErrors).length} onClick={() => { onSubmit(event as EventPerformance); }}>Submit</button>
        <button className="btn btn-warning" onClick={() => { onCancel(); }}>Cancel</button>
      </div>
    </div>
  );
}

export default EventSCRUDForm;